"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";

// Kbd: generated by UIX from the design system. Same variants and sizes as the Figma component.

const kbdVariants = cva(
  "inline-flex items-center justify-center text-fg-secondary rounded-sm",
  {
    variants: {
      appearance: {
        default: "bg-subtle border border-line-default shadow-[0_1px_0_rgb(0_0_0/0.12)]",
        ghost: "",
      },
      size: {
        sm: "h-5 px-1-5 text-label-small",
        md: "h-6 px-1-5 text-label-medium",
      },
    },
    defaultVariants: {
      appearance: "default",
      size: "md",
    },
  },
);

export interface KbdProps
  extends React.HTMLAttributes<HTMLElement>,
    VariantProps<typeof kbdVariants> {}

const Kbd = React.forwardRef<HTMLElement, KbdProps>(
  ({ className, appearance, size, ...props }, ref) => (
    <kbd data-slot="kbd" data-kind="chip" ref={ref} className={cn(kbdVariants({ appearance, size }), className)} {...props} />
  ),
);
Kbd.displayName = "Kbd";

export { Kbd, kbdVariants };
